import hashlib
import hmac
from urllib.parse import quote


def canonical_string(method, path, query, timestamp, body):
    q = "&".join(quote(name, safe="-_.~") + "=" + quote(value, safe="-_.~") for name, value in sorted(query))
    return "\n".join([method.upper(), path, q, str(timestamp), hashlib.sha256(body or b"").hexdigest()])


def _signature(secret, canonical):
    return hmac.new(secret, canonical.encode("utf-8"), hashlib.sha256).hexdigest()


def sign(secret, method, path, query, body, timestamp):
    return {"X-Timestamp": str(timestamp), "X-Signature": _signature(secret, canonical_string(method, path, query, timestamp, body))}


def verify(secret, method, path, query, body, headers, now, tolerance=300):
    lower = {k.lower(): v for k, v in headers.items()}
    stamp = lower.get("x-timestamp")
    received = lower.get("x-signature")
    if stamp is None or received is None or not stamp.isdigit():
        return False
    timestamp = int(stamp)
    if abs(now - timestamp) > tolerance:
        return False
    expected = _signature(secret, canonical_string(method, path, query, timestamp, body))
    return hmac.compare_digest(expected, received)
